input.newString:
import { cacheLife, cacheTag } from 'next/cache'
import { getPosts } from '@/lib/api'

async function getCachedPosts() {
  'use cache'
  cacheLife('hours')
  cacheTag('posts')
  return getPosts()
}

export default async function Home() {
  const posts = await getCachedPosts()

  return (
    <main>
      <h1>Blog Posts</h1>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <h2>{post.title}</h2>
            <p>By {post.author}</p>
          </li>
        ))}
      </ul>
    </main>
  )
}

